import json,re,hashlib
from html import unescape
from html.parser import HTMLParser
from pathlib import Path
class TextParser(HTMLParser):
 def __init__(self):super().__init__();self.out=[];self.tags=[];self.attrs=[]
 def handle_starttag(self,t,a):
  self.tags.append(t);self.attrs.extend(a)
  if t in ['p','br','div','li','tr','td','th']:self.out.append(' ')
 def handle_data(self,d):self.out.append(d)
 def handle_endtag(self,t):
  if t in ['p','div','li','tr','td','th']:self.out.append(' ')
def plain(t):
 p=TextParser();p.feed(t);return re.sub(r'\\s+',' ',''.join(p.out)).strip()
s=json.load(open('source.json'));a=json.load(open('answer.json'))
allowed=set('p br table thead tbody tfoot tr th td b strong i em u sup sub ul ol li div span blockquote'.split())
assert len(a)==len(s)==5
errors=[]
for x,y in zip(s,a):
 for k in ['code_id','source_id','source_sha256','number']:
  if x[k]"'!=y[k]:errors.append((x['"'number'],k,'identifier'))
 required=['proposed_xml','reason','review_notes','status','substantive_impact']
 for k in required:assert k in y,(x['number'],k)
 p=y['proposed_xml']
 si=y['substantive_impact'];assert si['version']==1
 for k in ['assessment','scope_limitations','new_burdens_review']:assert len(si[k])>=40
 if x.get('benefit_check_required'):assert len(y.get('benefit_review',''))>=100
 if p is None:
  assert y['status']=='retained_unchanged' and y['classification']==si['classification']=='retained_necessary' and si['effects']==[]
 else:
  parser=TextParser();parser.feed(p)
  assert set(parser.tags)<=allowed
  assert not parser.attrs
  assert y['status']=='rewrite_draft'
  assert y['change_type']=='normative_reduction'
  assert y['reform_policy_id']=='editorial_direction_2026_10_19'
  assert all(len(z)>=30 for z in y['removed_provisions'])
  for i,e in enumerate(si['effects']):
   assert set(e)==set('kind measure_id description before after unit affected_population conditions_and_transition replacement_or_new_burdens source_quote proposed_quote'.split())
   assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) and 6<=len(e['measure_id'])<=96
   for k,t in [('source_quote',x['source_xml']),('proposed_quote',p)]:
    q=e[k]
    if len(q)<12 or q not in plain(t):errors.append((x['number'],i,k,q))
 print(x['number'],y['status'],si['classification'],'effets',len(si['effects']),'source',len(x['source_xml']),'proposition',len(p or ''),'identité avec brouillon',plain(p or '')==plain(x['previous_draft']['proposed_xml']))
assert not errors,errors
print('Contrôles JSON, identifiants, citations exactes, balises, statuts et métadonnées : OK')
print('Empreintes des textes sources conservées :', [x['source_sha256'] for x in s])
print('Taille answer.json :',Path('answer.json').stat().st_size)
PY"

